function replaceLiteralFragment(value: string, source: string, replacement: string): string {
  // Le parole semplici devono essere sostituite solo come token autonomi: ad
  // esempio, tradurre "Kiosk" non deve corrompere l'identificatore FreeKiosk.
  if (/^[\p{L}\p{N}_]+$/u.test(source)) {
    const escaped = source.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    return value.replace(new RegExp(`(^|[^\\p{L}\\p{N}_])(${escaped})(?=$|[^\\p{L}\\p{N}_])`, 'gu'), (_match, prefix) => `${prefix}${replacement}`);
  }
  return value.split(source).join(replacement);
}

export function translateSourceText(value: string): string {
  if (typeof value !== 'string' || !value) return value;
  if (currentLang === 'it') return value;

  const translations = LITERAL_TRANSLATIONS[currentLang] || LITERAL_TRANSLATIONS.it;
  const leading = value.match(/^\s*/)?.[0] || '';
  const trailing = value.match(/\s*$/)?.[0] || '';
  const source = value.trim();

  // 1. Direct dictionary match
  const direct = translations[value] || translations[source];
  if (direct) return `${leading}${direct}${trailing}`;

  // 2. Dynamic pattern: "Glossario aggiornato: X termini pronti in 5 lingue."
  const glossaryMatch = source.match(/^Glossario aggiornato:\s*(\d+)\s*termini pronti in 5 lingue\.?$/i);
  if (glossaryMatch) {
    const count = glossaryMatch[1];
    if (currentLang === 'en') return `${leading}Glossary updated: ${count} terms ready in 5 languages.${trailing}`;
    if (currentLang === 'fr') return `${leading}Glossaire mis à jour : ${count} termes prêts en 5 langues.${trailing}`;
    if (currentLang === 'es') return `${leading}Glosario actualizado: ${count} términos listos en 5 idiomas.${trailing}`;
    if (currentLang === 'de') return `${leading}Glossar aktualisiert: ${count} Begriffe in 5 Sprachen bereit.${trailing}`;
  }

  // 3. Dynamic pattern: "X termini pronti in 5 lingue."
  const termsCountMatch = source.match(/^(\d+)\s*termini pronti in 5 lingue\.?$/i);
  if (termsCountMatch) {
    const count = termsCountMatch[1];
    if (currentLang === 'en') return `${leading}${count} terms ready in 5 languages.${trailing}`;
    if (currentLang === 'fr') return `${leading}${count} termes prêts en 5 langues.${trailing}`;
    if (currentLang === 'es') return `${leading}${count} términos listos en 5 idiomas.${trailing}`;
    if (currentLang === 'de') return `${leading}${count} Begriffe in 5 Sprachen bereit.${trailing}`;
  }

  // 4. Dynamic pattern: "X prodotti in Y categorie"
  const prodCatMatch = source.match(/^(\d+)\s*prodotti\s*in\s*(\d+)\s*categorie$/i);
  if (prodCatMatch) {
    const [, p, c] = prodCatMatch;
    if (currentLang === 'en') return `${leading}${p} products in ${c} categories${trailing}`;
    if (currentLang === 'fr') return `${leading}${p} produits dans ${c} catégories${trailing}`;
    if (currentLang === 'es') return `${leading}${p} productos en ${c} categorías${trailing}`;
    if (currentLang === 'de') return `${leading}${p} Produkte in ${c} Kategorien${trailing}`;
  }

  // 5. Menu & Gastro term translation engine
  try {
    const menuTrans = translateCustomerMenuText(source, currentLang);
    if (menuTrans && menuTrans !== source) {
      return `${leading}${menuTrans}${trailing}`;
    }
  } catch {}

  // 6. Handles UI messages that include fragments
  let translated = value;
  const entries = Object.entries(translations)
    .filter(([s]) => s.length >= 3 && s !== translated)
    .sort(([a], [b]) => b.length - a.length);
  for (const [sourceText, targetText] of entries) {
    if (translated.includes(sourceText)) translated = replaceLiteralFragment(translated, sourceText, targetText);
  }
  return translated;
}

